-- Standard safe drop
DROP TABLE IF EXISTS obsolete_logs;

-- Drop table and all dependent views/foreign keys (handle with extreme caution!)
DROP TABLE IF EXISTS categories CASCADE;

-- Fast, logged wipe of a table and its children
TRUNCATE TABLE order_items, orders RESTART IDENTITY CASCADE;

-- Reset a sequence explicitly (e.g. after DELETE)
ALTER SEQUENCE orders_id_seq RESTART WITH 1;

-- Drop a whole schema and everything in it
DROP SCHEMA IF EXISTS staging CASCADE;

-- Drop a database, terminating connections first (PG 13+)
DROP DATABASE IF EXISTS old_app WITH (FORCE);
